import axios from 'axios'

const url = 'http://localhost:3001/api/persons'

const getData = ()=>
  {
    const request = axios.get(url)
    return request.then(res => res.data)
  }

const postData = (newPerson) =>
  {
    const request = axios.post(url,newperson)
    return request.then(res => res.data)
  }

